41: /// Where user-writable state (`.env`, `data/`) lives.
42: ///
43: /// Portable builds and dev checkouts keep everything next to the app, like on
44: /// Windows. A Linux package installs under `/usr/lib` (and an AppImage mounts
45: /// a read-only squashfs), so writing there fails. In that case use the XDG
46: /// data dir: `$XDG_DATA_HOME/novatts` or `~/.local/share/novatts`.
47: #[cfg(target_os = "linux")]
48: fn linux_state_dir(handle: &tauri::AppHandle) -> Option<PathBuf> {
49:     let bundled = app_base_dir(handle);
50:     if dir_is_writable(&bundled) {
51:         return None;
52:     }
53:     let data_home = std::env::var_os("XDG_DATA_HOME")
54:         .map(PathBuf::from)
55:         .filter(|p| !p.as_os_str().is_empty())
56:         .or_else(|| {
57:             std::env::var_os("HOME")
58:                 .map(|h| PathBuf::from(h).join(".local").join("share"))
59:         })
60:         .unwrap_or_else(|| PathBuf::from("."));
61:     Some(data_home.join("novatts"))
62: }
63: 
64: #[cfg(not(target_os = "linux"))]
65: fn linux_state_dir(_handle: &tauri::AppHandle) -> Option<PathBuf> {
66:     None
67: }
